script.lang:
SELECT setval('amp_quartz_job_class_seq',
    greatest(coalesce((SELECT max(jc_id) FROM amp_quartz_job_class), 0),
             (SELECT last_value FROM amp_quartz_job_class_seq), 1), true);

INSERT INTO amp_quartz_job_class (jc_id, jc_name, jc_class_fullname)
SELECT nextval('amp_quartz_job_class_seq'), 'CDIP NDC indicator dashboard export',
       'org.digijava.module.message.jobs.AmpCdipIndicatorFundingJob'
WHERE NOT EXISTS (
    SELECT 1 FROM amp_quartz_job_class
    WHERE jc_class_fullname = 'org.digijava.module.message.jobs.AmpCdipIndicatorFundingJob'
);
